*/
import "C"
import (
 "crypto/sha256"
 "unsafe"
)
//export fastsha
func fastsha(p unsafe.Pointer, n C.longlong, out unsafe.Pointer) {
 b := unsafe.Slice((*byte)(p), int(n))
 s := sha256.Sum256(b)
 copy(unsafe.Slice((*byte)(out), 32), s[:])
}
func main() {}
